c81f5c70d9044"},{6,"dc5g_47ab7b3837cb07"},{40,3800},{12,"dc5h_19b523fbe86fdf"},{25,true},{55,true},{19,"0.97~1.65M"},{8,"pet_000641"},{2,{1,{{94,false},{72,false},{70,"PetAvatar_3800.png"},{58,"PetPortrait_DiYinLian2.png"},{29,"PetPortrait_DiYinLian2_yise.png"},{89,"PetAvatar_3800_1.png"}}}},{64,"dc5l_58d1c32e695803"},{75,"地面"},{84,"地底银鳞"},{73,"472"},{74,40},{67,"地系"},{101,{1,{{68,"2026-11-05"}}}},{11,{2,{}}},{31,2},{78,{1,{{66,42},{103,66},{80,80},{34,98},{96,96},{57,96}}}},{59,"地底银鳞"},{100,{2,{"地系"}}},{36,"65~105KG"}}}},{5,{1,{{27,true},{33,true},{44,{2,{250}}},{85,"自然类精灵"},{26,"地绡银龙说，遛弯时候最常遇到的是洛克，洛克们总是灰头土脸，看起来饥肠辘辘，分给他们矿石他们也不吃，真奇怪。拉布朗矿山的老矿工们感受到善意，努力不让地绡银龙扫兴，定期组织一队人马扛着水桶爬到山谷里，帮它搓背。"},{104,{1,{{61,"pet_000640"}}}},{81,{2,{1}}},{62,"dc5e_6c81f5c70d9044"},{6,"dc5g_47ab7b3837cb07"},{40,3801},{12,"dc5h_edde2657580089"},{25,true},{55,true},{19,"2.1~4.3M"},{8,"pet_000642"},{2,{1,{{94,false},{72,false},{70,"PetAvatar_3801.png"},{58,"PetPortrait_DiYinLian3.png"},{29,"PetPortrait_DiYinLian3_yise.png"},{89,"PetAvatar_3801_1.png"}}}},{64,"dc5l_58d1c32e695803"},{75,"地面"},{84,"地绡银龙"},{73,"473"},{74,40},{67,"地系"},{101,{1,{{68,"2026-11-05"}}}},{11,{2,{}}},{31,3},{78,{1,{{66,53},{103,82},{80,100},{34,123},{96,120},{57,120}}}},{59,"地绡银龙"},{100,{2,{"地系"}}},{36,"340~770KG"}}}},{54,{1,{{27,true},{33,true},{44,{2,{1000}}},{85,"自然类精灵"},{26,"一天里绝大多数时候，沉金兽都在溪水里不动，就算洛克靠近也懒得动弹。水流从它们头顶的金嵴上淌过，会把杂质带走，它们长期泡过的河段，河沙会泛起一层淡淡的金光。"},{104,{1,{{49,{2,{{1,{{26,"购买「圣龙通行证-金山」闪耀契约礼券获得的珍贵精灵蛋，经过孵化可以得到“异色”外观、“了不起”天分、且支持自选性格、个体资质的沉金兽。"},{30,"Item_150876.png"},{20,true},{84,"异色沉金兽的蛋"},{51,{2,{"购买「圣龙通行证-金山」闪耀契约礼券"}}}}}}}},{1,{2,{{1,{{26,"通过观察其花纹可以看出，这是沉金兽的果实。"},{30,"Item_108259.png"},{84,"沉金兽的果实"},{51,{2,{"圣龙通行证获得"}}},{102,false}}}}}}}}},{81,{2,{1}}},{62,"dc5e_d92e4fbb814ad4"},{6,"dc5g_d6123e8a7d96bf"},{40,3802},{12,"dc5h_331f9488973b5f"},{25,true},{55,true},{19,"0.55~0.7M"},{8,"pet_000643"},{2,{1,{{17,"Item_149255.png"},{1,{2,{"Item_108259.png"}}},{94,true},{72,true},{70,"PetAvatar_3802.png"},{58,"PetPortrait_Ch